 static Vector3 Read(BinaryReader r)=>new Vector3(r.ReadSingle(),r.ReadSingle(),r.ReadSingle());
 static float Difference(Vector3[] a,Vector3[] b){float error=0;for(int j=0;j<a.Length;j++)error=Mathf.Max(error,Vector3.Distance(a[j],b[j]));return error;}
 static Vector3[] Skin(SkinnedMeshRenderer r,Transform root){var m=r.sharedMesh;var p=m.vertices;var delta=new Vector3[p.Length];for(int s=0;s<m.blendShapeCount;s++){float w=r.GetBlendShapeWeight(s)*.01f;if(w==0)continue;m.GetBlendShapeFrameVertices(s,0,delta,null,null);for(int j=0;j<p.Length;j++)p[j]+=delta[j]*w;}var mat=r.bones.Select((b,j)=>root.worldToLocalMatrix*b.localToWorldMatrix*m.bindposes[j]).ToArray();var result=new Vector3[p.Length];using(var counts=m.GetBonesPerVertex())using(var weights=m.GetAllBoneWeights()){int at=0;for(int j=0;j<p.Length;j++)for(int k=0;k<counts[j];k++){var w=weights[at++];result[j]+=mat[w.boneIndex].MultiplyPoint3x4(p[j])*w.weight;}}return result;}
