 var root=PrefabUtility.LoadPrefabContents(Folder+"Liora_Candidate.prefab");var source=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/_Sandbox/Characters/Liora/Liora_73_Baked.fbx");
 try{
 var errors=root.GetComponent<Character>().ValidateConfiguration();errors.AddRange(root.GetComponent<CharacterFlowController>().ValidateConfiguration());if(errors.Count>0)throw new Exception(string.Join(";",errors));
 var animator=root.GetComponentInChildren<Animator>(true);if(root.GetComponentsInChildren<Animator>(true).Length!=1||!animator.avatar.isValid||!animator.avatar.isHuman)throw new Exception("Invalid Animator/Avatar");
 var skins=root.GetComponentsInChildren<SkinnedMeshRenderer>(true);var face=skins.Single(r=>r.name=="BAKED_head_lod0_mesh");var sync=root.GetComponent<CharacterFacialMeshSync>();
 int missing=root.GetComponentsInChildren<Transform>(true).Sum(t=>GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject));if(missing!=0)throw new Exception("Missing scripts");
 foreach(var r in skins)if(r.bones.Any(b=>!b||!b.IsChildOf(animator.transform)))throw new Exception("Renderer outside consolidated skeleton "+r.name);
 var references=new List<string>();foreach(var c in root.GetComponentsInChildren<Component>(true).Where(c=>c&&!(c is Transform))){var so=new SerializedObject(c);var it=so.GetIterator();while(it.Next(true)){
 if(it.propertyPath.StartsWith("m_")||it.propertyType!=SerializedPropertyType.ObjectReference||!it.objectReferenceValue)continue;var value=it.objectReferenceValue;var owner=(value as Component)?.transform??(value as GameObject)?.transform;
 if(owner&&owner!=root.transform&&!owner.IsChildOf(root.transform))references.Add(c.GetType().Name+"."+it.propertyPath+" -> "+AssetDatabase.GetAssetPath(value));
 }}if(references.Count>0)throw new Exception("Stale character object references: "+string.Join(";",references));
 var primary=new List<object>();var inactiveChannels=new List<object>();
 foreach(var original in source.GetComponentsInChildren<SkinnedMeshRenderer>(true)){
 var actual=skins.Single(r=>r.name==original.name);var om=original.sharedMesh;var am=actual.sharedMesh;
 if(!om.vertices.SequenceEqual(am.vertices)||!om.triangles.SequenceEqual(am.triangles)||om.blendShapeCount!=am.blendShapeCount)throw new Exception("Base mesh changed "+actual.name);
 var op=new Vector3[om.vertexCount];var on=new Vector3[op.Length];var ot=new Vector3[op.Length];var ap=new Vector3[op.Length];var an=new Vector3[op.Length];var at=new Vector3[op.Length];float maxPosition=0,maxNormal=0,maxTangent=0;
 for(int s=0;s<om.blendShapeCount;s++){if(om.GetBlendShapeName(s)!=am.GetBlendShapeName(s))throw new Exception("Shape name changed");om.GetBlendShapeFrameVertices(s,0,op,on,ot);am.GetBlendShapeFrameVertices(s,0,ap,an,at);if(!op.SequenceEqual(ap)||!on.SequenceEqual(an)||!ot.SequenceEqual(at))throw new Exception("Shape records changed "+actual.name);maxPosition=Mathf.Max(maxPosition,op.Max(p=>p.magnitude));maxNormal=Mathf.Max(maxNormal,on.Max(p=>p.magnitude));maxTangent=Mathf.Max(maxTangent,ot.Max(p=>p.magnitude));}
 float error=Difference(Skin(original,source.transform),Skin(actual,root.transform));if(error>2e-6f)throw new Exception("Neutral mismatch "+actual.name+" "+error);primary.Add(new{actual.name,vertices=am.vertexCount,shapes=am.blendShapeCount,allShapeArraysBitIdentical=true,maxNeutralErrorM=error});
 if(actual.name=="BAKED_body_lod0_mesh"||actual.name=="BAKED_Outfits")inactiveChannels.Add(new{actual.name,maxPosition,maxNormal,maxTangent});
 }
 var facial=new List<object>();foreach(var name in new[]{"Eyebrows","Eyelashes"}){var mesh=skins.Single(r=>r.name==name).sharedMesh;using(var r=new BinaryReader(File.OpenRead(Data+name+".bin"))){int n=r.ReadInt32(),tri=r.ReadInt32(),count=r.ReadInt32();r.BaseStream.Position=12L+n*32L+tri*4L;var p=new Vector3[n];var norm=new Vector3[n];var ap=new Vector3[n];var an=new Vector3[n];var t=new Vector3[n];
 for(int s=0;s<count;s++){for(int j=0;j<n;j++)p[j]=Read(r);for(int j=0;j<n;j++)norm[j]=Read(r);mesh.GetBlendShapeFrameVertices(s,0,ap,an,t);if(!p.SequenceEqual(ap)||!norm.SequenceEqual(an)||t.Any(v=>v.sqrMagnitude>0))throw new Exception("Facial groom saved record mismatch "+name+" "+s);}
 facial.Add(new{name,vertices=n,triangles=tri/3,shapes=count,allPositionAndNormalArraysBitIdentical=true,actualMeshMiB=UnityEngine.Profiling.Profiler.GetRuntimeMemorySizeLong(mesh)/1048576f});}}
 int syncChecks=0;foreach(var name in Enumerable.Range(0,face.sharedMesh.blendShapeCount).Select(face.sharedMesh.GetBlendShapeName)){int index=face.sharedMesh.GetBlendShapeIndex(name);face.SetBlendShapeWeight(index,37);sync.Apply();foreach(var r in skins.Where(r=>r!=face&&r.sharedMesh.blendShapeCount>0)){int j=r.sharedMesh.GetBlendShapeIndex(name);if(j<0||Mathf.Abs(r.GetBlendShapeWeight(j)-37)>.001f)throw new Exception("Facial sync failed "+r.name+" "+name);syncChecks++;}face.SetBlendShapeWeight(index,0);sync.Apply();}
 var lip=root.GetComponentInChildren<uLipSync.uLipSync>(true);var driver=root.GetComponentInChildren<uLipSync.uLipSyncBlendShape>(true);if(lip.onLipSyncUpdate.GetPersistentEventCount()!=1||lip.onLipSyncUpdate.GetPersistentTarget(0)!=driver||driver.skinnedMeshRenderer!=face)throw new Exception("Lip-sync event mismatch");
 var hair=root.GetComponentInChildren<HairInstance>(true);var group=hair.strandGroupProviders[0].hairAsset.strandGroups.Single();if(group.strandParticleCount!=32||hair.settingsExecutive.updateSimulationInEditor||hair.settingsExecutive.updateSimulationRate!=HairInstance.SettingsExecutive.UpdateRate.Fixed30Hz||hair.strandGroupDefaults.settingsGeometry.strandScale!=HairSim.SettingsGeometry.StrandScale.Fixed)throw new Exception("Hair production settings invalid");
 var head=animator.GetBoneTransform(HumanBodyBones.Head);var boundary=hair.settingsEnvironment.boundaryResident.Single();if(!hair.transform.IsChildOf(head)||!boundary.transform.IsChildOf(head)||hair.settingsEnvironment.boundaryCapture)throw new Exception("Head attachment invalid");
 var warmup=new SerializedObject(root.GetComponent<CharacterHairStartupWarmup>());if(warmup.FindProperty("targetAnimator").objectReferenceValue!=animator||warmup.FindProperty("strandHair").GetArrayElementAtIndex(0).objectReferenceValue!=hair)throw new Exception("Hair warmup wiring invalid");
 var gaze=(Transform)new SerializedObject(root.GetComponentInChildren<ExpressionModule>(true)).FindProperty("speechGaze.head").objectReferenceValue;if(Vector3.Dot(gaze.forward,root.transform.forward)<.999f||Vector3.Dot(gaze.up,root.transform.up)<.999f)throw new Exception("Gaze frame axes invalid");
 var hm=JObject.Parse(File.ReadAllText(Data+"groom_export.json"))["normalized_head_matrix"];var expected=new Matrix4x4();for(int row=0;row<4;row++)for(int col=0;col<4;col++)expected[row,col]=(float)hm[row][col];float endpoints=0;
 for(int j=0;j<group.strandCount;j++){HairAssetUtility.DeclareStrandIterator(group,j,out int start,out int step,out int end);foreach(var k in new[]{start,start+31*step})endpoints=Mathf.Max(endpoints,Vector3.Distance(expected.MultiplyPoint3x4(group.particlePosition[k]),root.transform.InverseTransformPoint(hair.transform.TransformPoint(group.particlePosition[k]))));}if(endpoints>2e-6f)throw new Exception("Groom world frame changed "+endpoints);
 var before=head.localRotation;head.localRotation=before*Quaternion.Euler(15,25,-5);bool follow=hair.transform.IsChildOf(head)&&boundary.transform.IsChildOf(head)&&(hair.transform.lossyScale-Vector3.one).magnitude<1e-4f;head.localRotation=before;
 var report=new{passed=true,configurationErrors=errors,missingScripts=missing,animators=1,humanoid=true,primaryMeshes=primary,facialHair=facial,synchronizedShapeChecks=syncChecks,lipSyncCallback=true,phonemes=driver.blendShapes.Count,noStaleCharacterReferences=true,inactiveChannelAudit=inactiveChannels,hair=new{strands=group.strandCount,points=32,simulationHz=30,editModeSimulation=false,maxWorldEndpointErrorM=endpoints,headAndCollisionFollow=follow,gazeAxesValid=true},sourceSceneSaved=false,playModeTested=false};File.WriteAllText(Data+"static_verification.json",JsonConvert.SerializeObject(report,Formatting.Indented));return new{passed=true,meshChecks=primary.Count,facialMeshChecks=facial.Count,syncChecks,maxHairEndpointErrorM=endpoints};
 }finally{PrefabUtility.UnloadPrefabContents(root);}
 }
 public static object Motion(){
 if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Edit Mode required");var root=PrefabUtility.LoadPrefabContents(Folder+"Liora_Candidate.prefab");
 try{var animator=root.GetComponentInChildren<Animator>(true);var skins=root.GetComponentsInChildren<SkinnedMeshRenderer>(true).Where(r=>r.enabled).ToArray();var rest=root.GetComponentsInChildren<Transform>(true).ToDictionary(t=>t,t=>(t.localPosition,t.localRotation,t.localScale));var neutral=skins.ToDictionary(r=>r,r=>Skin(r,root.transform));Action reset=()=>{foreach(var p in rest){p.Key.localPosition=p.Value.Item1;p.Key.localRotation=p.Value.Item2;p.Key.localScale=p.Value.Item3;}};
 var definitions=AssetDatabase.FindAssets("t:AnimationDefinition",new[]{"Assets/_Sandbox/Data"}).Select(AssetDatabase.GUIDToAssetPath).Select(AssetDatabase.LoadAssetAtPath<AnimationDefinition>).Where(d=>d&&d.Clip&&d.Clip.isHumanMotion).GroupBy(d=>d.Clip).Select(g=>g.First()).ToArray();var samples=new List<object>();
 foreach(var definition in definitions){reset();var graph=PlayableGraph.Create("Liora disposable motion verification");try{graph.SetTimeUpdateMode(DirectorUpdateMode.Manual);var p=AnimationClipPlayable.Create(graph,definition.Clip);p.SetApplyFootIK(false);AnimationPlayableOutput.Create(graph,"pose",animator).SetSourcePlayable(p);graph.Play();var movement=skins.ToDictionary(r=>r,r=>0f);float radius=0;
 foreach(float phase in new[]{0f,.25f,.5f,.75f,1f}){p.SetTime(definition.Clip.length*phase);graph.Evaluate(0);foreach(var r in skins){var v=Skin(r,root.transform);float bound=v.Max(x=>x.magnitude);if(!float.IsFinite(bound)||bound>3f)throw new Exception("Invalid motion "+definition.name+" "+r.name+" "+bound);radius=Mathf.Max(radius,bound);movement[r]=Mathf.Max(movement[r],Difference(v,neutral[r]));}}
 if(movement.Values.Max()<.001f)throw new Exception("Clip produces no motion "+definition.name);samples.Add(new{name=definition.name,clip=definition.Clip.name,maxRadiusM=radius,bodyMovementM=movement.Single(x=>x.Key.name=="BAKED_body_lod0_mesh").Value,outfitMovementM=movement.Single(x=>x.Key.name=="BAKED_Outfits").Value});}finally{graph.Destroy();}}
 reset();int fingers=0;foreach(var side in new[]{"Left","Right"})foreach(var finger in new[]{"Thumb","Index","Middle","Ring","Little"})foreach(var joint in new[]{"Proximal","Intermediate","Distal"}){var human=(HumanBodyBones)Enum.Parse(typeof(HumanBodyBones),side+finger+joint);var bone=animator.GetBoneTransform(human);if(!bone)throw new Exception("Missing finger "+human);bone.localRotation*=Quaternion.Euler(0,0,35);fingers++;reset();}
 if(samples.Count==0)throw new Exception("No Humanoid clips tested");var report=new{passed=true,fingerMappings=fingers,clips=samples,poseSamples=samples.Count*5,avatarHumanScale=animator.humanScale,playModeTested=false};File.WriteAllText(Data+"motion_verification.json",JsonConvert.SerializeObject(report,Formatting.Indented));return report;
 }finally{PrefabUtility.UnloadPrefabContents(root);}
 }
